function setInputByName(name,value){const el=document.querySelector(`input[name="${name}"]`);if(!el)return;el.value=value??"";el.dispatchEvent(new Event("input",{bubbles:true}));el.dispatchEvent(new Event("change",{bubbles:true}));}
function setLock(name,on){const lock=document.querySelector(`[data-lock-for="${name}"]`);if(lock)lock.hidden=!on;}
function prefillProfile(profile){if(!profile)return;const last=(profile.last_name||"").trim();const first=(profile.first_name||"").trim();setInputByName("last_name",last);setInputByName("first_name",first);setInputByName("phone",profile.phone);const ln=document.querySelector('input[name="last_name"]');const fn=document.querySelector('input[name="first_name"]');const lockLast=!!last;const lockFirst=!!first;if(ln){ln.readOnly=lockLast;ln.classList.toggle("tg-input-readonly",lockLast);}
if(fn){fn.readOnly=lockFirst;fn.classList.toggle("tg-input-readonly",lockFirst);}
setLock("last_name",lockLast);setLock("first_name",lockFirst);setComboboxValueByHiddenName("position",profile.position);setComboboxValueByHiddenName("salary_pickup_point",profile.pvz);setComboboxValueByHiddenName("salary_payment_method",profile.payment_method);setInputByName("salary_card_number",profile.salary_card);setInputByName("salary_phone_number",profile.salary_phone);setInputByName("salary_recipient",profile.recipient);setInputByName("bank_name",profile.bank);}
document.addEventListener("DOMContentLoaded",async()=>{tg?.ready?.();tg?.expand?.();const salaryMethodVisible=document.querySelector("[data-salary-payment-method]");showLoading(true);setFormDisabled(true);try{const{profile}=await loadProfile();prefillProfile(profile);}catch(err){console.error(err);alert(err?.message||"Ошибка загрузки профиля");}finally{setFormDisabled(false);const form=document.querySelector("form");requestAnimationFrame(()=>form?.__markClean?.());showLoading(false);}});function initProfileSubmit(){const form=document.querySelector("form");if(!form)return;form.addEventListener("submit",async(e)=>{e.preventDefault();if(typeof form.__isDirty==="function"&&!form.__isDirty())return;if(!validateStrictComboboxes(form))return;if(!form.reportValidity())return;const initData=tg?.initData||"";const fd=new FormData(form);showLoading(true);const submitBtn=form.querySelector('button[type="submit"], input[type="submit"]');if(submitBtn)submitBtn.disabled=true;try{const r=await fetch(`${prefix}/edit-profile`,{method:"POST",headers:{"X-Telegram-Init-Data":initData},body:fd,});const payload=await r.json().catch(()=>({}));if(!r.ok)throw new Error(payload.detail||"Ошибка сохранения");form.__markClean?.();try{tg?.HapticFeedback?.notificationOccurred("success");}catch(_){}
if(payload?.message){const msg=payload.message;if(payload.toast==="alert"){if(tg?.showAlert){tg.showAlert(msg,()=>{if(payload.close_on_ok)tg.close?.();});}else{alert(msg);if(payload.close_on_ok)tg.close?.();}}else{showSnack(msg,payload.duration_ms??4000);}}}catch(err){console.error(err);alert(err?.message||"Ошибка сохранения");try{tg?.HapticFeedback?.notificationOccurred("error");}catch(_){}}finally{if(submitBtn)submitBtn.disabled=false;showLoading(false);}});}
function validateStrictComboboxes(form){let ok=true;form.querySelectorAll('[data-combobox][data-combobox-mode="strict"]').forEach((root)=>{const input=root.querySelector("[data-combobox-input]");const valueInput=root.querySelector("[data-combobox-value]");if(!input)return;const required=input.hasAttribute("required")||valueInput?.hasAttribute("required")||root.dataset.comboboxRequired==="true";const selected=(valueInput?.value||"").trim();if(required&&!selected){const msg=root.dataset.comboboxInvalidMessage||"Выберите значение из списка";input.setCustomValidity(msg);input.reportValidity?.();ok=false;}else{input.setCustomValidity("");}});return ok;}
function initCardValidation(){const cardInputs=document.querySelectorAll("[data-card-mask]");const getDigits=(v)=>(v||"").replace(/\D/g,"");const luhnValid=(digits)=>{let sum=0;let alt=false;for(let i=digits.length-1;i>=0;i--){let n=digits.charCodeAt(i)-48;if(alt){n*=2;if(n>9)n-=9;}
sum+=n;alt=!alt;}
return sum%10===0;};const isVisible=(el)=>!!(el.offsetWidth||el.offsetHeight||el.getClientRects().length);const validateCard=(input)=>{if(input.disabled||!isVisible(input)){input.setCustomValidity("");return true;}
const digits=getDigits(input.value);if(!digits&&!input.required){input.setCustomValidity("");return true;}
if(!digits&&input.required){input.setCustomValidity("");return false;}
if(digits.length<16){input.setCustomValidity("Введите номер карты полностью");return false;}
input.setCustomValidity("");return true;};cardInputs.forEach((input)=>{input.addEventListener("input",()=>validateCard(input));input.addEventListener("blur",()=>validateCard(input));const form=input.closest("form");if(form){form.addEventListener("submit",(e)=>{const ok=validateCard(input);if(!ok){e.preventDefault();input.reportValidity();}});}});}
function ensureSnackHost(){let host=document.querySelector("[data-snack-host]");if(host)return host;host=document.createElement("div");host.setAttribute("data-snack-host","");document.body.appendChild(host);return host;}
function showSnack(message,durationMs=4000){const host=ensureSnackHost();host.innerHTML="";const el=document.createElement("div");el.className="snack";el.textContent=message||"";host.appendChild(el);requestAnimationFrame(()=>el.classList.add("is-visible"));window.setTimeout(()=>{el.classList.remove("is-visible");window.setTimeout(()=>{if(host.contains(el))host.removeChild(el);},220);},Math.max(500,durationMs));}